const open = indexedDB.open("viewer", 1);
open.onupgradeneeded = () =>
  open.result.createObjectStore("files", { keyPath: "name" });
open.onsuccess = () => {
  const blob = new Blob(["hi"], { type: "text/plain" });
  open.result.transaction("files", "readwrite")
    .objectStore("files").put({ name: "hi.txt", blob });
};
